import json
import sys

# Define the pathfinder tool
def find_path(start_x, start_y, end_x, end_y, map_id):
    # Obstacles per map_id
    # We add (24, 15) for map 0_61 as requested by the overwatch feedback
    obstacles = {
        '0_61': {
            # Rock walls and known solid obstacles
            (24, 15), (25, 15), (28, 15), (29, 15), (30, 15), (31, 15),
            (24, 16), (24, 17), (24, 18), (24, 19),
            # Cavern obstacles (TYPE_de37)
            (13, 22), (13, 23), (13, 24), (13, 25), (13, 26), (13, 27),
            (19, 14), (19, 15), (19, 16), (19, 17), (19, 18), (19, 19),
            (20, 19), (21, 19), (22, 19), (23, 19), (24, 19), (25, 19), (26, 19), (27, 19), (28, 19), (29, 19), (30, 19), (31, 19),
            # Rock walls on Rows 11/12
            (28, 12), (29, 12), (30, 12), (31, 12), (32, 12), (33, 12), (34, 12), (35, 12),
            (23, 11), (23, 10), (23, 9), (23, 8), (23, 7), (23, 6), (23, 5),
            (36, 7), (36, 6), (36, 5), (36, 4), (36, 3)
        },
        '0_60': {
            # Let's keep known B1F obstacles here if needed
        }
    }

    map_obstacles = obstacles.get(map_id, set())

    # A* Algorithm
    open_set = { (start_x, start_y) }
    came_from = {}
    g_score = { (start_x, start_y): 0 }
    f_score = { (start_x, start_y): abs(start_x - end_x) + abs(start_y - end_y) }

    while open_set:
        current = min(open_set, key=lambda pos: f_score.get(pos, float('inf')))
        if current == (end_x, end_y):
            # Reconstruct path
            path = []
            while current in came_from:
                prev = came_from[current]
                dx = current[0] - prev[0]
                dy = current[1] - prev[1]
                if dx == 1: path.append('Right')
                elif dx == -1: path.append('Left')
                elif dy == 1: path.append('Down')
                elif dy == -1: path.append('Up')
                current = prev
            path.reverse()
            return path

        open_set.remove(current)
        curr_x, curr_y = current

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            neighbor = (curr_x + dx, curr_y + dy)
            if neighbor in map_obstacles:
                continue
            # Simple boundary check for Mt. Moon maps
            if not (0 <= neighbor[0] <= 40 and 0 <= neighbor[1] <= 40):
                continue

            tentative_g = g_score[current] + 1
            if tentative_g < g_score.get(neighbor, float('inf')):
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g
                f_score[neighbor] = tentative_g + abs(neighbor[0] - end_x) + abs(neighbor[1] - end_y)
                open_set.add(neighbor)

    return None

