import json
import sys

try:
    input_data = json.loads(sys.argv[1])
except Exception:
    input_data = {}

start_x = int(input_data.get('start_x', 0))
start_y = int(input_data.get('start_y', 0))
end_x = int(input_data.get('end_x', 0))
end_y = int(input_data.get('end_y', 0))
map_id = input_data.get('map_id', '')

path = find_path(start_x, start_y, end_x, end_y, map_id)
if path:
    print(json.dumps(path))
else:
    print(json.dumps([]))
